-- Diagnostic wrappers generated by tools/validation/instrument_lua.py; edit bodies normally.
local APRTrace = APRInstrumentation and APRInstrumentation.Wrap or function(_, fn) return fn end
local APRYield = APRInstrumentation and APRInstrumentation.Yield or coroutine.yield
local APRResume = APRInstrumentation and APRInstrumentation.Resume or coroutine.resume
local APRPCall = APRInstrumentation and APRInstrumentation.PCall or pcall
-- Runs the local and world jobs under a shared frame budget, then publishes the result.

local Constants = APR.NavigationConstants.Navigation

local nav = APR.navigation
local Shared = APR.navigation._helpers
local ContextCurrent = Shared.ContextCurrent
local Distance = Shared.Distance
local Enabled = Shared.Enabled
local PlanningRequestCurrent = Shared.PlanningRequestCurrent
local Position = Shared.Position
local SpatialDistance = Shared.SpatialDistance

function nav:RunPlanningSearch(options)
    local context = options.context
    local generation = options.generation
    local data = options.data
    local start = options.start
    local goal = options.goal
    local step = options.step
    local walkingProvider = options.walkingProvider
    local keepPath = options.keepPath
    local keepDirect = options.keepDirect
    local reuseItinerary = options.reuseItinerary
    local preferLocal = options.preferLocal
    local walkSpeed = options.walkSpeed
    local walkSpeedFor = options.walkSpeedFor
    local updateStartedAt = options.updateStartedAt
    local seedDirect = options.seedDirect
    local waypointLeg = options.waypointLeg

    local previousSliceAt
    local coldTerrainSearch = walkingProvider ~= nil and not reuseItinerary
    local trackTerrainFrame = data.profile == "forever"
        and data.BeginTerrainFrame
        and data.HasDeferredTerrainImports
        and (
            data:HasDeferredTerrainImports(start.instanceID)
            or (goal.instanceID ~= start.instanceID and data:HasDeferredTerrainImports(goal.instanceID))
        )
    local function advance()
        if generation ~= self.generation or not ContextCurrent(context) or not self.search then return end
        if self.worldLoading then
            self._searchTimer, self.pausedWaypointSearch = nil, advance
            return
        end
        local job, inputs = self.search, self._routeInputs
        local terrainFrame = trackTerrainFrame and data:BeginTerrainFrame()
        local changed = self:HasPlanningInputsChanged(Position())
        if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
        if changed then
            self:RefreshStalePlanningInputs()
            return
        end
        if not Enabled() or (UnitIsDeadOrGhost and UnitIsDeadOrGhost("player")) then
            self:Cancel("inactive")
            return
        end
        if terrainFrame and terrainFrame.deferred then
            self._searchTimer = C_Timer.NewTimer(0, advance)
            return
        end
        -- With a clock, use the available time instead of yielding after a few
        -- cheap operations. The smaller fallback also bounds clients without it.
        local operationLimit = debugprofilestop and Constants.TIMED_OPERATION_LIMIT or Constants.UNTIMED_OPERATION_LIMIT
        local milliseconds = Constants.PLANNING_SLICE_MS
        local entryPrefix = self.walkingPrefix and job.entryWalkPreview and self.walkingPreview == job.entryWalkPreview
        local terrainSearch = job.phase == "search" or job.phase == "access_proof" or job.phase == "transit_proof"
        -- A verified transit prefix leaves the destination unplanned. Keep
        -- the frame-adaptive waypoint budget until the full comparison ends.
        local transitPrefix = self.travelPrefix
            and job.request
            and job.request.previewSameWorldTransit
            and job.phase == "search"
        local foreground = (self.localPathJob or coldTerrainSearch)
            and (
                self.state == "planning"
                or transitPrefix
                or job.phase == "waypoint_leg"
                or entryPrefix and terrainSearch
                or self.walkingPrefix and (self.localPathJob or job.phase == "transport")
            )
            and not keepPath
            and not keepDirect
            and debugprofilestop
            and walkingProvider
            and walkingProvider.RequiresWalkingProof
        if foreground then
            local now = debugprofilestop()
            -- Charge synchronous setup to the first slice. Keep a separate
            -- foreground allowance until the departure corridor can guide.
            if previousSliceAt then
                local interval = now - previousSliceAt
                if
                    step._mapWaypoint
                    and (self.state == "planning" or entryPrefix or transitPrefix)
                    and not self.localPathJob
                    and terrainSearch
                then
                    local cap = self.state == "planning"
                            and job.request
                            and job.request.previewEntryWalk
                            and Constants.FIRST_WALK_MAX_MS
                        or Constants.MAP_WAYPOINT_SEARCH_MAX_MS
                    milliseconds = math.max(1, math.min(cap, interval * 2 / 3))
                else
                    milliseconds = math.max(1, math.min(Constants.FIRST_WALK_MAX_MS, interval / 3))
                end
            else
                milliseconds = math.max(1, Constants.FIRST_SLICE_BUDGET_MS - (now - updateStartedAt))
            end
            previousSliceAt = now
        end
        if self.localPathJob then
            local localJob = self.localPathJob
            local started = debugprofilestop and debugprofilestop()
            local localState, localResult = localJob:Step(operationLimit, milliseconds)
            if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
            if localState == "planning" then
                self:UpdateWalkingPreview(localJob.walkingPreview, job)
                if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
            end
            if started then
                local elapsed = debugprofilestop() - started
                job.localSlices = (job.localSlices or 0) + 1
                job.localMilliseconds = (job.localMilliseconds or 0) + elapsed
                job.localMaxMilliseconds = math.max(job.localMaxMilliseconds or 0, elapsed)
                if APR.RecordPerformanceDuration then
                    APR:RecordPerformanceDuration("NavigationPlanningSlice", elapsed)
                end
            end
            if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
            if localState ~= "planning" then
                inputs.waitingForWalkingFloor = (preferLocal or step._service)
                        and start.indoors == true
                        and Distance(start, goal) <= Constants.LOCAL_WALK_YARDS
                        and localResult
                        and localResult.ambiguousFrom
                    or nil
                if localState == "ready" or localState == "partial" then
                    local published = self:PublishLocalPath(
                        localResult,
                        context,
                        generation,
                        job,
                        inputs,
                        false,
                        localState
                    )
                    if published and job.startedAt and not job.firstGuidanceMilliseconds and debugprofilestop then
                        job.firstGuidanceMilliseconds = debugprofilestop() - job.startedAt
                        if APR.RecordPerformanceDuration then
                            APR:RecordPerformanceDuration(
                                "NavigationFirstValidatedGuidance",
                                job.firstGuidanceMilliseconds
                            )
                        end
                    end
                    local sharedFloorChord = published and localResult.path[#localResult.path].sharedFloorChord
                    if
                        published
                        and (preferLocal or sharedFloorChord)
                        and type(localResult.yards) == "number"
                        and localResult.yards <= Constants.LOCAL_WALK_YARDS
                        and PlanningRequestCurrent(self, context, generation, job, inputs)
                    then
                        if
                            not sharedFloorChord and localState == "ready" and not localResult.partial
                            and job.request and job.request.allowTaxiStops and job.BeginTaxiStops
                        then
                            job.result = {
                                segments = { {
                                    kind = "walk", from = start, to = goal, path = localResult.path,
                                    seconds = localResult.seconds,
                                } },
                                totalSeconds = localResult.seconds,
                                totalCopper = 0,
                                localWalk = true,
                            }
                            if job:BeginTaxiStops() then
                                self.localPathJob = nil
                                self._searchTimer = C_Timer.NewTimer(0, advance)
                                return
                            end
                        end
                        job:Cancel()
                        self.search, self.localPathJob, self._searchTimer = nil, nil, nil
                        self._localWalk, self.recomputeKeepingPath = true, nil
                        self.lastPlanning = {
                            status = "ready",
                            phase = "local",
                            slices = job.localSlices,
                            totalSliceMilliseconds = job.localMilliseconds,
                            maxSliceMilliseconds = job.localMaxMilliseconds,
                            firstGuidanceMilliseconds = job.firstGuidanceMilliseconds,
                            elapsedMilliseconds = job.firstGuidanceMilliseconds,
                        }
                        return
                    end
                elseif
                    localState == "unavailable"
                    and not (localResult and localResult.unresolvedSurface)
                    and not (walkingProvider.RequiresWalkingProof and walkingProvider:RequiresWalkingProof(start, goal))
                then
                    -- Missing coverage uses the same authorized estimate as Search.
                    local speed = walkSpeedFor(start, goal)
                    if type(speed) ~= "number" or speed <= 0 or speed ~= speed or speed == math.huge then
                        speed = walkSpeed
                    end
                    self:PublishLocalPath(
                        { seconds = SpatialDistance(start, goal) / speed },
                        context,
                        generation,
                        job,
                        inputs,
                        true
                    )
                elseif localState == "cancelled" then
                    self:CancelLocalPath()
                    self:ForceRefresh()
                    self:RequestUpdate()
                    return
                end
                if self.localPathJob == localJob then self.localPathJob = nil end
            end
            if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
            if terrainFrame and terrainFrame.deferred then
                self._searchTimer = C_Timer.NewTimer(0, advance)
                return
            end
            local used = localJob.workLastStep
            if type(used) ~= "number" or used ~= used then used = operationLimit end
            operationLimit = math.max(0, operationLimit - math.max(1, used))
            if started then milliseconds = milliseconds - (debugprofilestop() - started) end
            -- Prioritize the small local query. Its existing continuation then
            -- resumes the full journey using the same operations/time budget.
            if self.localPathJob or operationLimit <= 0 or milliseconds <= 0 then
                self._searchTimer =
                    C_Timer.NewTimer(foreground and self.localPathJob and 0 or Constants.PLANNING_SLICE_DELAY, advance)
                return
            end
            milliseconds = math.min(milliseconds, Constants.PLANNING_SLICE_MS)
        end
        local state, result = job:Step(operationLimit, milliseconds)
        if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
        if
            self.waypointPendingLeg
            and self.waypointPendingLeg.transport
            and job.waypointLeg ~= self.waypointPendingLeg
        then
            if self.cursor > #self.queue then
                self:Cancel("transport_arrived")
                self:ForceRefresh("transport_arrived")
                self:RequestUpdate()
                return
            end
            self.waypointPendingLeg = nil
        end
        if state ~= "cancelled" and (state ~= "ready" or job.waypointLeg and job.waypointLeg.transport) then
            self:PublishTravelPrefix(job.travelPreview, job)
            if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
        end
        if self.waypointPreview ~= job.waypointPreview then
            self.waypointPreview = job.waypointPreview
            if state == "planning" then self:Notify() end
            if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
        end
        if state == "planning" and job.entryWalkPreview then
            self:UpdateWalkingPreview(job.entryWalkPreview, job)
            if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
        elseif state == "planning" and job.phase == "transport" then
            self:UpdateWalkingPreview(job.walkingPreview, job)
            if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
        elseif state == "planning" and job.phase == "search" and job.active and job.active.terrainJob then
            self:UpdateWalkingPreview(job.active.terrainJob.walkingPreview, job)
            if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
        elseif state ~= "planning" then
            self.walkingPreview = nil
        end
        if state ~= "planning" then
            self.lastPlanning = {
                status = state,
                slices = (job.slices or 0) + (job.localSlices or 0),
                firstGuidanceMilliseconds = job.firstGuidanceMilliseconds,
                elapsedMilliseconds = job.elapsedMilliseconds,
                totalSliceMilliseconds = (job.totalSliceMilliseconds or 0) + (job.localMilliseconds or 0),
                maxSliceMilliseconds = math.max(job.maxSliceMilliseconds or 0, job.localMaxMilliseconds or 0),
            }
        end
        self.waitingData = job.waitingData == true
        if job.lastSliceMilliseconds and APR.RecordPerformanceDuration then
            APR:RecordPerformanceDuration("NavigationPlanningSlice", job.lastSliceMilliseconds)
        end
        if state ~= "planning" and state ~= "cancelled" and APR.performanceLogging and APR.CountPerformanceEvent then
            APR:CountPerformanceEvent(
                job.zoneRouted and (state == "ready" and "NavigationZoneReady" or "NavigationZoneBlocked")
                    or "NavigationFullGraph"
            )
        end
        if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
        -- The accessible graph has already failed. Explanations may still
        -- inspect locked transports, but cannot produce guidance to a free pin.
        if
            step._mapWaypoint
            and self.state == "planning"
            and job.searchFailed
            and (job.phase == "explain" or job.phase == "explain_collect")
        then
            self.state = self.waitingData and "waiting_data" or "no_path"
            self:Notify()
            if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
        end
        -- Unfinished work publishes nothing. Its next slice checks live inputs
        -- before doing more work; repeating full observations twice in this
        -- callback only multiplies map/coordinate/secret-value queries. A
        -- terminal result must still be checked after providers and telemetry,
        -- which can change inputs or replace this request reentrantly.
        if state ~= "planning" then
            changed = self:HasPlanningInputsChanged(Position())
            if not PlanningRequestCurrent(self, context, generation, job, inputs) then return end
            if changed then
                self:RefreshStalePlanningInputs()
                return
            end
        end
        if state == "cancelled" then
            -- A provider changed while the graph was being prepared. Restart
            -- from fresh inputs instead of treating the interruption as failure.
            self:ForceRefresh()
            self:RequestUpdate()
        elseif state == "planning" then
            self._searchTimer = C_Timer.NewTimer(foreground and 0 or Constants.PLANNING_SLICE_DELAY, advance)
        elseif state == "ready" then
            result = result or self.search:GetResult()
            local first = result and result.segments and result.segments[1]
            if result and result.localWalk and not result.taxiDiscovery then
                self.search, self._searchTimer, self.recomputeKeepingPath = nil, nil, nil
                self._localWalk = true
            elseif inputs.waitingForWalkingFloor and first and first.sourceFree then
                -- A personal teleport does not resolve the walking departure.
                -- Retry the nearby objective on a fresh floor observation.
                self.waitingData, job.unresolvedSurface, job.unresolvedStartSurface = true, true, true
                local active = self:GetActiveStep()
                if active and active.sourceFree then self.recomputeKeepingPath = nil end
                self:SearchFailed()
            else
                self:Publish(result, context, generation)
            end
        else
            self:SearchFailed(job.blockers)
        end
    end--[[APR_DIAG]]; advance = APRTrace("APR-Core/features/navigation/controller/NavigationSearchLoop.lua:46:advance#2", advance)--[[/APR_DIAG]]
    -- MarkRouteReady would cancel this newly created search. Notify through
    -- the ordinary arrow/step refresh flow while faster alternatives continue.
    if seedDirect or waypointLeg then
        self:Notify()
    else
        self:Render()
        if self.state == "planning" and APR.NavigationAdapter and APR.NavigationAdapter.QueueWaypointRefresh then
            APR.NavigationAdapter:QueueWaypointRefresh()
        end
        if
            self.state == "planning"
            and data.profile == "forever"
            and not step._service
            and APR.Arrow
            and APR.Arrow.SetCoord
        then
            APR.Arrow:SetCoord()
        end
    end
    advance()
end--[[APR_DIAG]]; nav.RunPlanningSearch = APRTrace("APR-Core/features/navigation/controller/NavigationSearchLoop.lua:19:nav:RunPlanningSearch#1", nav.RunPlanningSearch)--[[/APR_DIAG]]
